import { NextRequest, NextResponse } from "next/server";
import { requireUser } from "@/lib/auth";
import { getBrandLogo, normaliseDomain } from "@/lib/mail/brand-logo";

export const dynamic = "force-dynamic";

/**
 * Sender brand logo for the mail client's avatars.
 *
 * AUTHENTICATED, deliberately. This endpoint makes an outbound request to a
 * domain named in the query string, so leaving it open would hand anyone a
 * fetcher that runs from our network. `requireUser` is the difference between
 * a feature and an open proxy — the guards in lib/mail/brand-logo.ts (https
 * only, public IPs only, size cap, timeout, image types only) are the second
 * layer, not the first.
 *
 * A miss is a 404 with a short cache: the avatar simply falls back to initials,
 * so there is nothing to report and no reason to retry it on every render.
 */
export async function GET(req: NextRequest) {
  // `requireUser` throws for a signed-out caller, which an API route turns into
  // a 500. The request is refused either way, but 500 says "we broke" when the
  // truth is "you are not signed in" — so answer it properly.
  try {
    await requireUser();
  } catch {
    return new NextResponse(null, { status: 401 });
  }

  const domain = normaliseDomain(req.nextUrl.searchParams.get("domain") ?? "");
  if (!domain) return new NextResponse(null, { status: 400 });

  const logo = await getBrandLogo(domain).catch(() => null);
  if (!logo) {
    return new NextResponse(null, {
      status: 404,
      headers: { "cache-control": "private, max-age=3600" },
    });
  }

  return new NextResponse(new Uint8Array(logo.body), {
    status: 200,
    headers: {
      "content-type": logo.contentType,
      // Private: this is per-account browsing behaviour, not something a shared
      // cache should hold. Immutable-ish for a day; the server cache is the one
      // that actually spares the upstream fetch.
      "cache-control": "private, max-age=86400",
      "x-logo-source": logo.source,
      // The response is an image built from a third party's bytes; make sure it
      // is never interpreted as anything else. SVG can carry script, so it must
