// Sender brand logos for the mail client.
//
// "Do these senders have an official logo assigned to their email?" — yes, and
// the standard for it is BIMI (Brand Indicators for Message Identification).
// A domain publishes a TXT record at `default._bimi.<domain>` carrying
// `l=<https url to an SVG>`, and that SVG is the logo the brand has formally
// asserted for its mail. That is the only source here that is genuinely
// "official"; it is also rare, because publishing it in earnest goes with a
// Verified Mark Certificate.
//
// A second tier falls back to the domain's own favicon. That is NOT an
// assertion by the sender about their mail — it is just their website's icon —
// so it is reported separately (`source`) and never presented as verified.
//
// WHERE THE FETCHING HAPPENS. All of it is server-side, and the browser only
// ever talks to us. If the client fetched these directly, opening a mailbox
// would announce every one of your correspondents' domains to those domains
// (and to whatever third-party favicon service was used). It also means one
// fetch per domain for the whole instance rather than one per reader.
//
// This module makes OUTBOUND requests to addresses derived from untrusted mail,
// so it is written as an SSRF boundary: https only, public IPs only, hard
// timeout, hard size cap, image content-types only, redirects re-checked.

import { promises as dns } from "node:dns";
import net from "node:net";

export type BrandLogo = {
  /** "bimi" = the sender formally published this. "favicon" = best-effort. */
  source: "bimi" | "favicon";
  contentType: string;
  body: Buffer;
};

const MAX_BYTES = 256 * 1024;
const FETCH_TIMEOUT_MS = 5_000;
const MAX_REDIRECTS = 2;

// BIMI mandates SVG Tiny PS; favicons are usually ico/png. Anything else is
// refused rather than passed through to the browser.
const ALLOWED_TYPES = new Set([
  "image/svg+xml",
  "image/png",
  "image/x-icon",
  "image/vnd.microsoft.icon",
  "image/jpeg",
  "image/webp",
  "image/gif",
]);

type Entry = { at: number; value: BrandLogo | null };
const CACHE = new Map<string, Entry>();
const HIT_TTL_MS = 24 * 60 * 60 * 1000;
// Negative results expire sooner: a domain can start publishing BIMI, and we
// should not be blind to that for a whole day. Still long enough that a busy
// mailbox is not re-resolving the same dozen domains all afternoon.
const MISS_TTL_MS = 6 * 60 * 60 * 1000;
const MAX_ENTRIES = 500;

export function normaliseDomain(input: string): string | null {
  const d = input.trim().toLowerCase().replace(/\.$/, "");
  // Hostname shape only — this value reaches DNS and a URL, so anything with a
  // slash, space, credential or port is rejected outright rather than escaped.
  if (!/^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/.test(d)) return null;
  return d;
}

/** True for anything that is not a normal, routable public address. */
function isPrivateAddress(ip: string): boolean {
  if (net.isIPv4(ip)) {
    const p = ip.split(".").map(Number);
    if (p[0] === 10) return true;
    if (p[0] === 127) return true;
    if (p[0] === 0) return true;
    if (p[0] === 172 && p[1] >= 16 && p[1] <= 31) return true;
    if (p[0] === 192 && p[1] === 168) return true;
    if (p[0] === 169 && p[1] === 254) return true; // link-local + cloud metadata
    if (p[0] === 100 && p[1] >= 64 && p[1] <= 127) return true; // CGNAT
    if (p[0] >= 224) return true; // multicast / reserved
    return false;
  }
  if (net.isIPv6(ip)) {
    const a = ip.toLowerCase();
    if (a === "::1" || a === "::") return true;
    if (a.startsWith("fe80") || a.startsWith("fc") || a.startsWith("fd")) return true;
    // IPv4-mapped (::ffff:10.0.0.1) has to be unwrapped or it slips straight past.
    const m = a.match(/::ffff:(\d+\.\d+\.\d+\.\d+)$/);
    if (m) return isPrivateAddress(m[1]);
    return false;
  }
  return true;
}

async function hostIsPublic(host: string): Promise<boolean> {
  // A literal IP in the URL never gets to skip the check.
  if (net.isIP(host)) return !isPrivateAddress(host);
  try {
    const addrs = await dns.lookup(host, { all: true });
    if (addrs.length === 0) return false;
    // EVERY address must be public: one public and one loopback A record is a
    // classic way to get a fetch pointed back inside.
    return addrs.every((a) => !isPrivateAddress(a.address));
  } catch {
    return false;
  }
}

/**
 * Fetch an image with every guard applied at each hop. Returns null on any
 * problem at all — this is decoration, so nothing here is worth an error.
 */
async function fetchImage(rawUrl: string): Promise<{ contentType: string; body: Buffer } | null> {
  let url: URL;
  try {
    url = new URL(rawUrl);
  } catch {
    return null;
  }

  for (let hop = 0; hop <= MAX_REDIRECTS; hop++) {
    if (url.protocol !== "https:") return null;
    if (!(await hostIsPublic(url.hostname))) return null;

    const ac = new AbortController();
    const timer = setTimeout(() => ac.abort(), FETCH_TIMEOUT_MS);
    let res: Response;
    try {
      res = await fetch(url, {
        redirect: "manual", // followed by hand so each hop is re-validated
        signal: ac.signal,
        headers: { accept: "image/svg+xml,image/png,image/*;q=0.8", "user-agent": "Nxeon-Mail-Logo/1.0" },
      });
    } catch {
      clearTimeout(timer);
      return null;
    }
    clearTimeout(timer);

    if (res.status >= 300 && res.status < 400) {
      const loc = res.headers.get("location");
      if (!loc) return null;
      try {
        url = new URL(loc, url);
      } catch {
        return null;
      }
      continue;
    }
    if (!res.ok || !res.body) return null;

    const type = (res.headers.get("content-type") ?? "").split(";")[0].trim().toLowerCase();
    if (!ALLOWED_TYPES.has(type)) return null;

    // Declared length is a hint, not a promise — the read loop below is what
    // actually enforces the cap.
    const declared = Number(res.headers.get("content-length") ?? "0");
    if (declared > MAX_BYTES) return null;

    const reader = res.body.getReader();
    const chunks: Uint8Array[] = [];
    let total = 0;
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      total += value.byteLength;
      if (total > MAX_BYTES) {
        await reader.cancel().catch(() => {});
        return null;
      }
      chunks.push(value);
    }
    return { contentType: type, body: Buffer.concat(chunks) };
  }
  return null;
}

/** The `l=` URL from a domain's BIMI record, if it publishes one. */
async function bimiLogoUrl(domain: string): Promise<string | null> {
  let records: string[][];
  try {
    records = await dns.resolveTxt(`default._bimi.${domain}`);
  } catch {
    return null;
  }
  for (const parts of records) {
    // TXT values arrive split into 255-byte chunks; a BIMI record's URL is
    // routinely long enough to be split mid-value, so join before parsing.
    const txt = parts.join("");
    if (!/^\s*v=BIMI1\s*;/i.test(txt)) continue;
    const tag = txt.split(";").map((s) => s.trim()).find((s) => /^l=/i.test(s));
    const value = tag?.slice(2).trim();
    if (value) return value;
  }
  return null;
}

function cacheGet(domain: string): Entry | undefined {
  const hit = CACHE.get(domain);
  if (!hit) return undefined;
  const ttl = hit.value ? HIT_TTL_MS : MISS_TTL_MS;

  const ttl = hit.value ? HIT_TTL_MS : MISS_TTL_MS;
  if (Date.now() - hit.at > ttl) {
    CACHE.delete(domain);
    return undefined;
  }
  return hit;
}

function cacheSet(domain: string, value: BrandLogo | null) {
  // Crude bound: a mailbox full of one-off senders should not grow this without
  // limit. Oldest insertion goes first — Map preserves insertion order.
  if (CACHE.size >= MAX_ENTRIES) {
    const oldest = CACHE.keys().next().value;
    if (oldest) CACHE.delete(oldest);
  }
  CACHE.set(domain, { at: Date.now(), value });
}

/**
 * The sender domain's logo, or null. Never throws.
 *
 * `allowFavicon` decides whether the non-authoritative second tier is used;
 * with it off, only a real BIMI record produces a logo.
 */
export async function getBrandLogo(
  rawDomain: string,
  opts: { allowFavicon?: boolean } = {},
): Promise<BrandLogo | null> {
  const domain = normaliseDomain(rawDomain);
  if (!domain) return null;

  const cached = cacheGet(domain);
  if (cached) return cached.value;

  const bimi = await bimiLogoUrl(domain);
  if (bimi) {
    const got = await fetchImage(bimi);
    // BIMI is specified as SVG; anything else claiming to be one is not it.
    if (got && got.contentType === "image/svg+xml") {
      const value: BrandLogo = { source: "bimi", contentType: got.contentType, body: got.body };
      cacheSet(domain, value);
      return value;
    }
  }

  if (opts.allowFavicon !== false) {
    const got = await fetchImage(`https://${domain}/favicon.ico`);
    if (got && got.body.length > 0) {
      const value: BrandLogo = { source: "favicon", contentType: got.contentType, body: got.body };
      cacheSet(domain, value);
      return value;
    }
  }

  cacheSet(domain, null);
  return null;
}
