/**
 * Does `pathname` belong to `href`? Exact match, or a detail route beneath it
 * (`/admin/users/123`). The bare "/admin" only ever matches exactly so it can
 * never swallow every deeper route.
 */
export function hrefMatches(href: string, pathname: string): boolean {
  if (pathname === href) return true;
  if (href === "/admin") return false;
  return pathname.startsWith(href + "/");
}

/** The item (and its group) owning `pathname`, by longest matching href. */
export function navItemForPath(
  pathname: string,
  groups: AdminNavGroup[] = ADMIN_NAV_GROUPS,
): { group: AdminNavGroup; item: AdminNavItem; child?: AdminNavChild } | null {
  let best: { group: AdminNavGroup; item: AdminNavItem; child?: AdminNavChild; len: number } | null = null;
  for (const group of groups) {
    for (const item of group.items) {
      const cands: (AdminNavChild & { isChild?: boolean })[] = [item, ...(item.children ?? []).map((c) => ({ ...c, isChild: true }))];
      for (const c of cands) {
        if (c.pending) continue;
        if (hrefMatches(c.href, pathname) && (!best || c.href.length > best.len)) {
          best = { group, item, child: c.isChild ? c : undefined, len: c.href.length };
        }
      }
    }
  }
  return best ? { group: best.group, item: best.item, child: best.child } : null;
}

/**
 * Breadcrumb trail for a pathname: group › item › child › "Detail".
 * Detail routes (an id segment under a known href) get a trailing crumb.
 */
export function breadcrumbsForPath(pathname: string): { label: string; href?: string }[] {
  const hit = navItemForPath(pathname);
  if (!hit) return [{ label: "Admin", href: "/admin" }];
  const crumbs: { label: string; href?: string }[] = [];
  if (hit.group.label) crumbs.push({ label: hit.group.label });
  const itemHref = hit.item.children?.[0]?.href ?? hit.item.href;
  crumbs.push({ label: hit.item.label, href: itemHref });
  const leaf = hit.child ?? hit.item;
  if (hit.child && hit.child.href !== itemHref) crumbs.push({ label: hit.child.label, href: hit.child.href });
  if (pathname !== leaf.href && pathname.startsWith(leaf.href + "/")) {
    const rest = pathname.slice(leaf.href.length + 1);
    crumbs.push({ label: rest === "new" ? "New" : rest.includes("/") ? "Details" : "Details" });
  }
  return crumbs;
}

