/**
 * Pure trigger + persistence rules for first-run tours. No Prisma, no Next —
 * unit-tested directly by test/tours-trigger.test.ts.
 *
 * THE RULE: a tour auto-starts at most once per (user, serviceKey) — never
 * per server. A customer's first Minecraft server shows the Minecraft tour; the
 * second Minecraft server shows nothing; their first Valheim server shows the
 * Valheim tour; their first VPS shows the VPS tour.
 */

import type { TourStatus } from "./types";

/** Global "don't show me tours again" opt-out row. */
export const TOUR_OPT_OUT_KEY = "*";

/** Fixed, non-game service keys. Game keys are `game:<family>`. */
export const FIXED_SERVICE_KEYS = ["vps", "hosting", "email", "domain"] as const;

/** Families are lowercase slugs in lib/games.ts (`minecraft`, `sdtd`, `plutoniumt4`). */
const GAME_KEY = /^game:[a-z0-9]{2,32}$/;

/** Only values this matches are ever written to UserTourProgress.serviceKey. */
export function isValidServiceKey(k: unknown): k is string {
  if (typeof k !== "string") return false;
  if (k === TOUR_OPT_OUT_KEY) return true;
  if ((FIXED_SERVICE_KEYS as readonly string[]).includes(k)) return true;
  return GAME_KEY.test(k);
}

/** The serviceKey a Server row belongs to. `family` is the GAME family (game plan's first), or null for a VPS. */
export function serviceKeyForServer(s: { isGame: boolean; family: string | null | undefined }): string {
  if (s.isGame && s.family) {
    const f = s.family.toLowerCase();
    if (GAME_KEY.test(`game:${f}`)) return `game:${f}`;
  }
  return "vps";
}

/** A server older than this when first opened never auto-starts its tour (pre-launch fleet). */
export const AUTO_START_MAX_AGE_DAYS = 30;

export type AutoStartInput = {
  /** The signed-in viewer owns the service (not an admin looking at someone else's). */
  isOwner: boolean;
  /** An admin is impersonating the customer — never auto-start, never persist. */
  impersonating: boolean;
  /** The service finished provisioning (Server RUNNING / hosting ACTIVE / …). */
  ready: boolean;
  /** The page is showing a provisioning/"it's live" interstitial instead of the panel. */
  interstitial?: boolean;
  /** Existing progress row for this serviceKey, if any. */
  progress: { status: TourStatus | string } | null;
  /** The user opted out of tours globally (row with serviceKey "*"). */
  optedOut: boolean;
  /** When the service was created — guards against greeting a months-old server with "it's ready". */
  createdAt: Date;
  now?: Date;
};

export type AutoStartDecision =
  | { start: false; reason: string }
  | { start: true; resumeAt: number; fresh: boolean };

/**
 * Should the tour open by itself on this page load?
 * `resumeAt` is the step to open on (an interrupted run — reload mid-tour —
 * resumes where it was; a fresh run starts at 0).
 */
export function shouldAutoStart(i: AutoStartInput & { lastStep?: number }): AutoStartDecision {
  if (i.impersonating) return { start: false, reason: "impersonating" };
  if (!i.isOwner) return { start: false, reason: "not-owner" };
  if (!i.ready) return { start: false, reason: "not-ready" };
  if (i.interstitial) return { start: false, reason: "interstitial" };
  if (i.optedOut) return { start: false, reason: "opted-out" };
  if (i.progress) {
    if (i.progress.status === "STARTED") {
      return { start: true, resumeAt: Math.max(0, i.lastStep ?? 0), fresh: false };
    }
    return { start: false, reason: "seen" };
  }

