export type TourWriteResult = { ok: true; persisted: boolean } | { ok: false; error: string };

function parseEvent(raw: unknown): TourEvent | null {
  if (!raw || typeof raw !== "object") return null;
  const e = raw as { type?: unknown; step?: unknown };
  const step = typeof e.step === "number" ? e.step : undefined;
  switch (e.type) {
    case "start":
      return { type: "start" };
    case "step":
      return step === undefined ? null : { type: "step", step };
    case "complete":
      return { type: "complete", step };
    case "dismiss":
      return { type: "dismiss", step };
    default:
      return null;
  }
}

