console.log(r,"footer links",links.length,"short tap targets(<24px):",links.filter(l=>l.r<24&&l.r>0).length, "socials:", links.filter(l=>/twitter|x\.com|discord|youtube|instagram|tiktok|facebook|reddit|github/i.test(l.h||"")).length);
}
